-- Classic 1.60 (WoW Forever): quest level and minimum level as the official beta sends them (classic_re/sniff/sniff_quest_levels.py,
-- SMSG_QUERY_QUEST_INFO_RESPONSE). Overrides the vanilla levels and the quest level - 3 guess for every sniffed quest. Safe to run again.
ON DUPLICATE KEY UPDATE `LevelType` = VALUES(`LevelType`), `QuestLevel` = VALUES(`QuestLevel`);
ON DUPLICATE KEY UPDATE `QuestLevel` = VALUES(`QuestLevel`), `MinLevel` = VALUES(`MinLevel`);
